<script setup lang="ts">
import type { BsWeighingCopy, BsWeighingForm, BsWeighingKind, BsWeighingPicker, BsWeighingRow, BsWeighingView } from '../types/weighingSetupPresentation'
const props=defineProps<{copy:BsWeighingCopy;view:BsWeighingView;rows:BsWeighingRow[];products:BsWeighingPicker}>()
const mode=defineModel<BsWeighingKind>('mode',{required:true}),search=defineModel<string>('search',{required:true}),page=defineModel<number>('page',{required:true}),historyPage=defineModel<number>('historyPage',{required:true})
const editorOpen=defineModel<boolean>('editorOpen',{required:true}),historyOpen=defineModel<boolean>('historyOpen',{required:true}),form=defineModel<BsWeighingForm>('form',{required:true})
const emit=defineEmits<{retry:[];retryHistory:[];add:[];edit:[id:string];history:[id:string];submit:[];product:[id:string];productSearch:[query:string];productMore:[];productRetry:[]}>()
function change<K extends keyof BsWeighingForm>(key:K,value:BsWeighingForm[K]){form.value={...form.value,[key]:value}}
const columns=computed(()=>[{key:'name',field:'name',header:mode.value==='device'?props.copy.name:props.copy.product},{key:'detail',field:'detail',header:mode.value==='device'?props.copy.model:props.copy.unit},{key:'value',field:'value',header:mode.value==='device'?props.copy.serial:props.copy.factor},{key:'evidence',field:'evidence',header:props.copy.evidence},{key:'status',field:'status',header:props.copy.active},{key:'revision',field:'revision',header:props.copy.revision},{key:'actions',header:props.copy.history}])
const historyColumns=computed(()=>[{key:'revision',field:'revision',header:props.copy.revision},{key:'reason',field:'reason',header:props.copy.reason},{key:'changes',field:'changes',header:props.copy.changes},{key:'actor',field:'actor',header:props.copy.actor},{key:'date',field:'date',header:props.copy.date}])
const connectionFields=computed(()=>[{key:'baudRate' as const,label:props.copy.baud,values:['1200','2400','4800','9600','19200','38400','57600','115200']},{key:'dataBits' as const,label:props.copy.dataBits,values:['7','8']},{key:'stopBits' as const,label:props.copy.stopBits,values:['1','2']},{key:'parity' as const,label:props.copy.parity,values:['none','even','odd']},{key:'flowControl' as const,label:props.copy.flow,values:['none','hardware']}])
</script>
<template>
 <BsStack gap="lg">
  <BsPageHeader :title="copy.title" :subtitle="copy.subtitle"><template #actions><BsLink to="/pos">{{ copy.manual }}</BsLink><BsButton v-if="view.canManage" :disabled="view.locked || editorOpen || historyOpen" @click="emit('add')">{{ copy.add }}</BsButton></template></BsPageHeader>
  <BsText v-if="!view.available">{{ copy.noShop }}</BsText>
  <BsStack v-else gap="md">
   <BsSelect :model-value="mode" :label="copy.mode" :options="view.modes" option-label="label" option-value="value" :disabled="view.locked || editorOpen || historyOpen" @update:model-value="mode=String($event) as BsWeighingKind" />
   <BsDataTable v-model:search="search" :value="rows" :columns="columns" data-key="id" :label="mode === 'device' ? copy.devices : copy.factors" searchable lazy paginator :rows="20" :first="(page-1)*20" :total-records="view.total" :loading="view.loading" :error="view.error" @page="page=$event.page+1" @retry="emit('retry')"><template #cell-actions="{row}"><BsInline wrap><BsButton :disabled="view.locked || editorOpen || historyOpen" variant="secondary" @click="emit('edit',row.id)">{{ copy.edit }}</BsButton><BsButton :disabled="view.locked || editorOpen || historyOpen" variant="text" @click="emit('history',row.id)">{{ copy.history }}</BsButton></BsInline></template><template #empty><BsText>{{ copy.empty }}</BsText></template></BsDataTable>
  </BsStack>
  <BsRecordActionDialog v-model:visible="editorOpen" :title="view.editor.title" :dirty="view.editor.dirty" :pending="view.editor.pending" :close-blocked="view.locked" :error="view.editor.error" :submit-label="copy.save" :cancel-label="copy.cancel" :submit-disabled="view.editor.unitLoading" pinned-actions size="lg" @submit="emit('submit')">
   <BsText as="p" tone="muted">{{ view.editor.notice }}</BsText>
   <template v-if="mode === 'device'">
    <BsGrid :columns="2"><BsField v-slot="f" for="weighing-label" :label="copy.name"><BsInput :id="f.id" :model-value="form.label" required :maxlength="120" :disabled="view.locked" @update:model-value="change('label',String($event))" /></BsField><BsField v-slot="f" for="weighing-model" :label="copy.model"><BsInput :id="f.id" :model-value="form.model" required :maxlength="120" :disabled="view.locked" @update:model-value="change('model',String($event))" /></BsField></BsGrid>
    <BsField v-slot="f" for="weighing-serial" :label="copy.serial"><BsInput :id="f.id" :model-value="form.serialNumber" required :maxlength="64" :disabled="view.locked" @update:model-value="change('serialNumber',String($event))" /></BsField>
    <BsGrid :columns="2"><BsField v-for="field in connectionFields" :key="field.key" v-slot="f" :for="`weighing-${field.key}`" :label="field.label"><BsSelect :input-id="f.id" :label="field.label" :model-value="form[field.key]" :options="field.values.map(value=>({value,label:value}))" option-label="label" option-value="value" :disabled="view.locked" @update:model-value="change(field.key,String($event))" /></BsField></BsGrid>
   </template>
   <template v-else>
    <BsEntityPicker :model-value="form.productId" :label="copy.product" :options="products.options" option-label="name" option-value="id" :loading="products.loading" :error="products.error" :has-more="products.hasMore" :load-more-label="copy.more" :retry-label="copy.retry" :disabled="view.locked || view.editor.identityLocked" @update:model-value="emit('product',String($event??''))" @search="emit('productSearch',$event)" @load-more="emit('productMore')" @retry="emit('productRetry')" />
    <BsText as="p">{{ copy.unit }}: {{ view.editor.unit || '—' }}</BsText>
    <BsField v-slot="f" for="weighing-factor" :label="copy.factor"><BsInput :id="f.id" :model-value="form.kgPerBaseUnit" inputmode="decimal" required :disabled="view.locked || view.editor.unitLoading" @update:model-value="change('kgPerBaseUnit',String($event))" /></BsField>
   </template>
   <BsField v-slot="f" for="weighing-evidence" :label="copy.evidence"><BsTextarea :id="f.id" :model-value="form.evidenceReference" required :minlength="3" :maxlength="500" :disabled="view.locked" @update:model-value="change('evidenceReference',String($event))" /></BsField>
   <BsCheckbox :model-value="form.active" :label="copy.active" :disabled="view.locked" @update:model-value="change('active',Boolean($event))" />
   <BsCheckbox :model-value="form.confirmed" :label="mode === 'device' ? copy.confirmDevice : copy.confirmFactor" :disabled="view.locked" @update:model-value="change('confirmed',Boolean($event))" />
   <BsField v-slot="f" for="weighing-reason" :label="copy.reason"><BsTextarea :id="f.id" :model-value="form.reason" required :minlength="3" :maxlength="500" :disabled="view.locked" @update:model-value="change('reason',String($event))" /></BsField>
  </BsRecordActionDialog>
  <BsDialog v-model:visible="historyOpen" :title="view.history.title" size="lg"><BsText v-if="view.history.loading" role="status">{{ copy.retry }}</BsText><BsStack v-else-if="view.history.error"><BsText role="alert">{{ view.history.error }}</BsText><BsButton @click="emit('retryHistory')">{{ copy.retry }}</BsButton></BsStack><BsStack v-else gap="md"><BsDescriptionList><BsDescriptionItem v-for="field in view.history.fields" :key="field.label" :term="field.label">{{ field.value }}</BsDescriptionItem></BsDescriptionList><BsDataTable :value="view.history.events" :columns="historyColumns" data-key="id" :label="copy.history" lazy paginator :rows="20" :first="(historyPage-1)*20" :total-records="view.history.total" @page="historyPage=$event.page+1" /></BsStack><template #footer="{ close }"><BsButton @click="close">{{ copy.close }}</BsButton></template></BsDialog>
 </BsStack>
</template>
